45	  template <typename F, std::size_t... Is>
46	  __attribute__((always_inline))
47	  constexpr void unroll_for_impl(std::index_sequence<Is...>, F&& f) {
48	    (f(std::integral_constant<std::size_t, Is>{}), ...);
49	  }
