57	  template <typename T>
58	  struct raw_unsigned {
59	    using type = std::conditional_t<(sizeof(T) == 1), uint8_t,
60	      std::conditional_t<(sizeof(T) == 2), uint16_t,
61	        std::conditional_t<(sizeof(T) == 4), uint32_t,
62	          uint64_t>>>;
63	  };
64	  template <typename T>
65	  using raw_unsigned_t = typename raw_unsigned<T>::type;
