67	  template <typename T, typename D>
68	  struct data_accessor_t {
69	    using Type = typename T::dtype;
70	
71	    static __attribute__((always_inline)) D bit_fill(Type src) {
72	      static_assert(sizeof(D) % sizeof(Type) == 0, "D must be a multiple of Type in size");
73	      if constexpr (std::is_same_v<Type, D>) {
74	        return src; // passthrough
75	      } else {
76	        constexpr uint32_t count = sizeof(D) / sizeof(Type);
77	        constexpr uint32_t bits = 8 * sizeof(Type);
78	        using US = raw_unsigned_t<Type>;
79	        using UD = raw_unsigned_t<D>;
80	        auto src_u = *reinterpret_cast<const US*>(&src); // unsigned cast
81	        auto src_d = static_cast<UD>(src_u); // zero-extend
82	        UD result_u(0);
83	        detail::unroll_for<count>([&](auto i) {
84	          result_u |= (src_d << (i * bits));
85	        });
86	        return *reinterpret_cast<const D*>(&result_u);
87	      }
88	    }
89	
90	    static __attribute__((always_inline)) D pack_row(const Type *base, uint32_t ldm) {
91	      static_assert(sizeof(D) % sizeof(Type) == 0, "D must be a multiple of Type in size");
92	      if constexpr (sizeof(Type) == 1 && sizeof(D) == 4) {
93	        // 4 × 1-byte strided loads → single pack-load byte instruction
94	        return vx_packlb_f(base, ldm);
95	      } else if constexpr (sizeof(Type) == 2 && sizeof(D) == 4) {
96	        // 2 × 2-byte strided loads → single pack-load halfword instruction
97	        return vx_packlh_f(base, ldm * 2u);
98	      } else {
99	        constexpr uint32_t count = sizeof(D) / sizeof(Type);
100	        constexpr uint32_t bits = 8 * sizeof(Type);
101	        using US = raw_unsigned_t<Type>;
102	        using UD = raw_unsigned_t<D>;
103	        UD result_u(0);
104	        detail::unroll_for<count>([&](auto i) {
105	          auto src_u = *reinterpret_cast<const US*>(base); // unsigned cast
106	          auto src_d = static_cast<UD>(src_u); // zero-extend
107	          result_u |= (src_d << (i * bits));
108	          base += ldm; // next row
109	        });
110	        return *reinterpret_cast<const D*>(&result_u);
111	      }
112	    }
113	  };
