118	    static __attribute__((always_inline)) D bit_fill(uint8_t src) {
119	      constexpr uint32_t count = sizeof(D);
120	      assert((src & 0xf0) == 0 && "src must be a 4-bit value");
121	      using UD = raw_unsigned_t<D>;
122	      uint8_t src_u8 = (src << 4) | src; // pack 2 nibbles
123	      auto src_d = static_cast<UD>(src_u8); // zero-extend
124	      UD result_u(0);
125	      detail::unroll_for<count>([&](auto i) {
126	        result_u |= (src_d << (i * 8));
127	      });
128	      return *reinterpret_cast<const D*>(&result_u);
