153	template <uint32_t NT,              // number of threads per warp
154	          typename It,              // input type (A,B)
155	          typename Ot,              // output type (C,D)
156	          bool is_sparse = false,   // sparse mode flag
157	          uint32_t NR_ = 8,         // registers per C/D fragment
158	          uint32_t DK_ = 0          // K dimension of the tile
159	          >
160	struct wmma_context {
161	private:
162	  using cfg = wmma_config_t<NT, fp32, fp32, NR_, DK_>;
163	
164	  using vreg_t = float;
165	
166	  template <frag_use_t U, typename T, uint32_t N>
167	  struct fragment_t {
168	    using Type = T;
169	    static constexpr frag_use_t Use = U;
170	    static constexpr uint32_t NR = N;
171	    std::array<vreg_t, N> data;
172	  };
173	
174	public:
175	
176	  using input_t  = typename It::dtype;
177	  using output_t = typename Ot::dtype;
178	
179	  using input_acessor_t = detail::data_accessor_t<It, vreg_t>;
180	  using output_acessor_t = detail::data_accessor_t<Ot, vreg_t>;
181	
182	  static constexpr uint32_t input_is_subbyte = (It::bits < 8);
183	  static constexpr bool input_is_mx = mx_scale_format(It::id);
184	
185	  static constexpr uint32_t i_ratio = sizeof(vreg_t) / sizeof(input_t);
186	  static constexpr uint32_t tileM = cfg::tileM;
187	  static constexpr uint32_t tileN = cfg::tileN;
188	  static constexpr uint32_t tileK = cfg::tileK * i_ratio;
189	
190	  // Sparse metadata constants (using actual It, not cfg's fp32 default)
191	  static constexpr uint32_t sp_rtl_i_ratio = 32 / It::bits;
192	  static constexpr uint32_t sp_meta_cols = (NT * 2 * sp_rtl_i_ratio + 31) / 32;
193	  static constexpr uint32_t sp_per_warp_depth = cfg::m_steps * (cfg::k_steps / 2);
194	  static constexpr uint32_t sp_cols_per_load = (NT >= sp_per_warp_depth) ? (NT / sp_per_warp_depth) : 1;
195	  static constexpr uint32_t sp_num_meta_loads = (sp_per_warp_depth * sp_meta_cols + NT - 1) / NT;
196	  static constexpr uint32_t meta_stride = sp_num_meta_loads * NT;
197	  static constexpr uint32_t sparse_k_steps = cfg::k_steps / 2;
198	  static constexpr uint32_t sparse_regs = cfg::m_steps * sparse_k_steps;
199	  static constexpr uint32_t a_k_stride_sp = tileK / 2;
200	
201	  // WGMMA_SP smem metadata layout constants (smem stored immediately after compressed A)
202	  // meta_row_w: bits per tcM row = tcK * 2 * (32/It::bits)
203	  // wg_meta_stride_bytes: bytes per (step_m, step_k) bank = ceil(tcM * meta_row_w / 32) * 4
204	  static constexpr uint32_t wg_meta_banks        = cfg::m_steps * (cfg::k_steps / 2);
205	  static constexpr uint32_t wg_meta_row_bits      = cfg::tcK * 2 * sp_rtl_i_ratio;
206	  static constexpr uint32_t wg_meta_stride_words  = (cfg::tcM * wg_meta_row_bits + 31) / 32;
207	  static constexpr uint32_t wg_meta_stride_bytes  = wg_meta_stride_words * 4;
208	  static constexpr uint32_t wg_meta_total_bytes   = wg_meta_banks * wg_meta_stride_bytes;
209	
210	  using fragment_a   = fragment_t<frag_use_t::matrix_a, input_t, cfg::NRA>;
211	  using fragment_b   = fragment_t<frag_use_t::matrix_b, input_t, cfg::NRB>;
212	  using fragment_acc = fragment_t<frag_use_t::accumulator, output_t, cfg::NRC>;
213	
214	  // Emits one TCU_LD per metadata-load batch; for sp_num_meta_loads == 2,
215	  // emits two TCU_LDs into separate slots to match the sparse-meta-phase counter.
216	  template <typename Frag>
217	  static __attribute__((always_inline)) void load_sp_metadata(Frag& frag, const void* meta_sp_ptr) {
218	    static_assert(is_sparse, "load_sp_metadata requires sparse configuration");
219	    static_assert(Frag::Use == frag_use_t::matrix_a, "sparse metadata load is only valid for matrix_a fragment");
220	    (void)frag;
221	    uintptr_t addr = reinterpret_cast<uintptr_t>(meta_sp_ptr);
222	    __asm__ volatile (".insn r %[insn], 2, 2, x0, %[base], x%[fmt]"
223	      :
224	      : [insn]"i"(RISCV_CUSTOM0),
225	        [base]"r"(addr),
226	        [fmt]"i"(It::id)
227	      : "memory"
228	    );
229	    if constexpr (sp_num_meta_loads == 2) {
230	      uintptr_t addr2 = addr + (NT * sizeof(float));
231	      __asm__ volatile (".insn r %[insn], 2, 2, x1, %[base], x%[fmt]"
232	        :
233	        : [insn]"i"(RISCV_CUSTOM0),
234	          [base]"r"(addr2),
235	          [fmt]"i"(It::id)
236	        : "memory"
237	      );
238	    }
239	  }
240	
241	  // Load one warp-wide packed MX scale array into the independent A or B
242	  // metadata SRAM. rd[4] selects the MX namespace; rd[0] selects the axis.
243	  template <typename Frag>
244	  static __attribute__((always_inline)) void load_mx_metadata(Frag& frag, const void* meta_mx_ptr) {
245	    static_assert(input_is_mx, "load_mx_metadata requires an MX input format");
246	    static_assert(Frag::Use == frag_use_t::matrix_a || Frag::Use == frag_use_t::matrix_b,
247	                  "MX metadata load is only valid for matrix_a or matrix_b fragments");
248	    (void)frag;
249	    uintptr_t addr = reinterpret_cast<uintptr_t>(meta_mx_ptr);
250	    if constexpr (Frag::Use == frag_use_t::matrix_a) {
251	      __asm__ volatile (".insn r %[insn], 2, 2, x16, %[base], x%[fmt]"
252	        :
253	        : [insn]"i"(RISCV_CUSTOM0), [base]"r"(addr), [fmt]"i"(It::id)
254	        : "memory"
255	      );
256	    } else {
257	      __asm__ volatile (".insn r %[insn], 2, 2, x17, %[base], x%[fmt]"
258	        :
259	        : [insn]"i"(RISCV_CUSTOM0), [base]"r"(addr), [fmt]"i"(It::id)
260	        : "memory"

