265	  template <typename Frag, typename T>
266	  static __attribute__((always_inline)) void fill_fragment(Frag &dst, T value) {
267	    vreg_t fill_data;
268	    if constexpr (Frag::Use == frag_use_t::accumulator) {
269	      fill_data = output_acessor_t::bit_fill(value);
270	    } else {
271	      fill_data = input_acessor_t::bit_fill(value);
272	    }
273	    detail::unroll_for<Frag::NR>([&](auto r) {
274	      vreg_t tmp;
275	      __asm__ volatile("fmv.s %0, %1" : "=f"(tmp): "f"(fill_data));
276	      dst.data[r] = tmp;
277	    });
278	  }
279	
280	  template <mem_layout src_layout = row_major, typename Frag>
281	  static __attribute__((always_inline)) void load_matrix_sync(Frag &dst, const void *src, size_t ldm) {
282	    uint32_t lane = vx_thread_id();
283	    if constexpr (Frag::Use == frag_use_t::matrix_a) {
284	      // Load row-major matrix A
285	      uint32_t block_idx = (cfg::a_block_size == NT) ? 0 : (lane / cfg::a_block_size);
286	      uint32_t lane_in_blk = (cfg::a_block_size == NT) ? lane : (lane % cfg::a_block_size);
287	      uint32_t block_row = (lane_in_blk / cfg::tcK) + (block_idx * cfg::tcM);
288	      uint32_t block_col = (lane_in_blk % cfg::tcK) * i_ratio;
289	      uint32_t m_stride  = cfg::a_sub_blocks * cfg::tcM;
290	      uint32_t k_stride  = cfg::tcK * i_ratio;
291	      if constexpr (src_layout == col_major) {
292	        std::swap(block_row, block_col);
293	      }
294	      if constexpr (is_sparse) {
295	        // Sparse A load: only load half the K-steps (compressed A)
296	        constexpr uint32_t sparse_k_steps = cfg::k_steps / 2;
297	        constexpr uint32_t sparse_regs = cfg::m_steps * sparse_k_steps;
298	        auto base = reinterpret_cast<const input_t*>(src) + block_row * ldm + block_col;
299	        detail::unroll_for<sparse_regs>([&](auto r) {
300	          uint32_t block_m  = r / sparse_k_steps;
301	          uint32_t block_k  = r % sparse_k_steps;
302	          uint32_t elem_row = block_m * m_stride;
303	          uint32_t elem_col = block_k * k_stride;
304	          if constexpr (src_layout == col_major) {
305	            static_assert(input_is_subbyte == false, "col_major layout is not supported for sub-byte matrix_a");
306	            std::swap(elem_row, elem_col);
307	            auto ptr = base + elem_row * ldm + elem_col;
308	            if constexpr (sizeof(vreg_t) == sizeof(input_t) && !input_is_subbyte) {
309	              dst.data[r] = *reinterpret_cast<const vreg_t*>(ptr);
310	            } else {
311	              dst.data[r] = input_acessor_t::pack_row(ptr, ldm);
312	            }
313	          } else {
314	            // row_major layout
315	            auto ptr = base + elem_row * ldm + elem_col;
316	            assert(reinterpret_cast<uintptr_t>(ptr) % alignof(vreg_t) == 0 && "pointer must be aligned to 4 bytes");
317	            dst.data[r] = *reinterpret_cast<const vreg_t *>(ptr);
318	          }
319	        });
320	      } else {
321	        // Dense A load: load all K-steps
322	        auto base = reinterpret_cast<const input_t*>(src) + block_row * ldm + block_col;
323	        detail::unroll_for<Frag::NR>([&](auto r) {
324	          uint32_t block_m  = r / cfg::k_steps;
325	          uint32_t block_k  = r % cfg::k_steps;
326	          uint32_t elem_row = block_m * m_stride;
327	          uint32_t elem_col = block_k * k_stride;
328	          if constexpr (src_layout == col_major) {
329	            static_assert(input_is_subbyte == false, "col_major layout is not supported for sub-byte matrix_a");
330	            std::swap(elem_row, elem_col);
331	            auto ptr = base + elem_row * ldm + elem_col;
332	            if constexpr (sizeof(vreg_t) == sizeof(input_t) && !input_is_subbyte) {
333	              dst.data[r] = *reinterpret_cast<const vreg_t*>(ptr);
334	            } else {
335	              dst.data[r] = input_acessor_t::pack_row(ptr, ldm);
336	            }
337	          } else {
338	            // raw_major layout
339	            auto ptr = base + elem_row * ldm + elem_col;
340	            assert(reinterpret_cast<uintptr_t>(ptr) % alignof(vreg_t) == 0 && "pointer must be aligned to 4 bytes");
341	            dst.data[r] = *reinterpret_cast<const vreg_t *>(ptr);
342	          }
343	        });
344	      }
345	
346	    } else if constexpr (Frag::Use == frag_use_t::matrix_b) {
347	      if constexpr (is_sparse) {
348	        // Sparse B load: uses 2x tcK for B block
349	        constexpr uint32_t b_tcK = cfg::tcK * 2;
350	        uint32_t block_idx = (cfg::b_block_size_sp == NT) ? 0 : (lane / cfg::b_block_size_sp);
351	        uint32_t lane_in_blk = (cfg::b_block_size_sp == NT) ? lane : (lane % cfg::b_block_size_sp);
352	        uint32_t block_col = (lane_in_blk / b_tcK) + (block_idx * cfg::tcN);
353	        uint32_t block_row = (lane_in_blk % b_tcK) * i_ratio;
354	        // NT=16 sparse: each register = 2 columns × full K (n_stride=2, no K iteration)
355	        // NT=8/32 sparse: standard interleaved layout
356	        uint32_t n_stride  = cfg::sym_sparse ? (cfg::tcN / 2) : (cfg::b_sub_blocks_sp * cfg::tcN);
357	        uint32_t k_stride  = b_tcK * i_ratio;
358	        if constexpr (src_layout == col_major) {
359	          std::swap(block_row, block_col);
360	        }
361	        auto base = reinterpret_cast<const input_t*>(src) + block_row * ldm + block_col;
362	
363	        if constexpr (src_layout == row_major) {
364	          static_assert(input_is_subbyte == false, "row_major layout is not supported for sub-byte matrix_b");
365	          // Pre-compute k-group base pointers (elem_row * ldm varies by k-group)
366	          constexpr uint32_t num_k_groups = cfg::sym_sparse ? 1 : (Frag::NR / cfg::b_sub_steps_sp);
367	          const input_t* k_bases[num_k_groups];
368	          k_bases[0] = base;
369	          if constexpr (num_k_groups >= 2) {
370	            asm volatile("" : "+r"(k_bases[0])); // prevent reverse strength reduction
371	            auto k_ldm_step = k_stride * (uint32_t)ldm;
372	            detail::unroll_for<num_k_groups - 1>([&](auto i) {
373	              k_bases[i + 1] = k_bases[i] + k_ldm_step;
374	            });
375	          }
376	          detail::unroll_for<Frag::NR>([&](auto r) {
377	            uint32_t block_k, block_n;
378	            if constexpr (cfg::sym_sparse) { block_k = 0; block_n = r; }
379	            else { block_k = r / cfg::b_sub_steps_sp; block_n = r % cfg::b_sub_steps_sp; }
380	            uint32_t elem_col = block_n * n_stride;
381	            auto ptr = k_bases[block_k] + elem_col;
382	            if constexpr (sizeof(vreg_t) == sizeof(input_t) && !input_is_subbyte) {
383	              dst.data[r] = *reinterpret_cast<const vreg_t*>(ptr);
384	            } else {
385	              dst.data[r] = input_acessor_t::pack_row(ptr, ldm);
386	            }
387	          });
388	        } else {
389	          // col_major: after swap, elem_row = block_n * n_stride, elem_col = block_k * k_stride
390	          // NT=16 sparse: each register = separate column group, so num_n_groups = NRB
391	          constexpr uint32_t num_n_groups = cfg::sym_sparse ? Frag::NR : cfg::b_sub_steps_sp;
392	          const input_t* n_bases[num_n_groups];
393	          n_bases[0] = base;
394	          if constexpr (num_n_groups >= 2) {
395	            asm volatile("" : "+r"(n_bases[0])); // prevent reverse strength reduction
396	            auto n_ldm_step = n_stride * (uint32_t)ldm;
397	            detail::unroll_for<num_n_groups - 1>([&](auto i) {
398	              n_bases[i + 1] = n_bases[i] + n_ldm_step;
399	            });
400	          }
401	          detail::unroll_for<Frag::NR>([&](auto r) {
402	            uint32_t block_k, block_n;
403	            if constexpr (cfg::sym_sparse) { block_k = 0; block_n = r; }
404	            else { block_k = r / cfg::b_sub_steps_sp; block_n = r % cfg::b_sub_steps_sp; }
405	            uint32_t elem_col = block_k * k_stride;
406	            auto ptr = n_bases[block_n] + elem_col;
407	            assert(reinterpret_cast<uintptr_t>(ptr) % alignof(vreg_t) == 0 && "pointer must be aligned to 4 bytes");
408	            dst.data[r] = *reinterpret_cast<const vreg_t *>(ptr);
409	          });
410	        }
411	      } else {
412	        // Dense B load
413	        uint32_t block_idx = (cfg::b_block_size == NT) ? 0 : (lane / cfg::b_block_size);
414	        uint32_t lane_in_blk = (cfg::b_block_size == NT) ? lane : (lane % cfg::b_block_size);
415	        uint32_t block_col = (lane_in_blk / cfg::tcK) + (block_idx * cfg::tcN);
416	        uint32_t block_row = (lane_in_blk % cfg::tcK) * i_ratio;
417	        uint32_t n_stride  = cfg::b_sub_blocks * cfg::tcN;
418	        uint32_t k_stride  = cfg::tcK * i_ratio;
419	        if constexpr (src_layout == col_major) {
420	          std::swap(block_row, block_col);
421	        }
422	        auto base = reinterpret_cast<const input_t*>(src) + block_row * ldm + block_col;
423	        detail::unroll_for<Frag::NR>([&](auto r) {
424	          uint32_t block_k = r / cfg::b_sub_steps;
425	          uint32_t block_n = r % cfg::b_sub_steps;
426	          uint32_t elem_row = block_k * k_stride;
427	          uint32_t elem_col = block_n * n_stride;
428	          if constexpr (src_layout == row_major) {
429	            static_assert(input_is_subbyte == false, "row_major layout is not supported for sub-byte matrix_b");
430	            auto ptr = base + elem_row * ldm + elem_col;
431	            if constexpr (sizeof(vreg_t) == sizeof(input_t) && !input_is_subbyte) {
432	              dst.data[r] = *reinterpret_cast<const vreg_t*>(ptr);
433	            } else {
434	              dst.data[r] = input_acessor_t::pack_row(ptr, ldm);
435	            }
436	          } else {
437	            // col_major layout
438	            std::swap(elem_row, elem_col);
439	            auto ptr = base + elem_row * ldm + elem_col;
440	            assert(reinterpret_cast<uintptr_t>(ptr) % alignof(vreg_t) == 0 && "pointer must be aligned to 4 bytes");
441	            dst.data[r] = *reinterpret_cast<const vreg_t *>(ptr);
442	          }
443	        });
444	      }
445	
446	    } else {
447	      // Load accumulator matrix C
448	      uint32_t block_row = lane / cfg::tcN;
449	      uint32_t block_col = lane % cfg::tcN;
450	      uint32_t m_stride = cfg::tcM;
451	      uint32_t n_stride = cfg::tcN;
452	      if constexpr (src_layout == col_major) {
453	        std::swap(block_row, block_col);
454	      }
455	      auto base = reinterpret_cast<const output_t*>(src) + block_row * ldm + block_col;
456	      detail::unroll_for<Frag::NR>([&](auto r) {
457	        uint32_t block_m  = r / cfg::n_steps;
458	        uint32_t block_n  = r % cfg::n_steps;
459	        uint32_t elem_row = block_m * m_stride;
460	        uint32_t elem_col = block_n * n_stride;
461	        if constexpr (src_layout == col_major) {
462	          std::swap(elem_row, elem_col);
463	        }
464	        auto ptr = base + elem_row * ldm + elem_col;
465	        if constexpr (sizeof(vreg_t) == sizeof(output_t)) {
466	          dst.data[r] = *reinterpret_cast<const vreg_t *>(ptr);
467	        } else {
468	          vreg_t tmp(0);
469	          *reinterpret_cast<output_t*>(&tmp) = *ptr;
470	          dst.data[r] = tmp;
471	        }
472	      });
473	    }
474	  }
475	
476	  template <mem_layout dst_layout = row_major, typename Frag>
477	  static __attribute__((always_inline)) void store_matrix_sync(void *dst, const Frag &src, size_t ldm) {
478	    static_assert(Frag::Use == frag_use_t::accumulator, "only accumulator fragment can be stored");
479	    uint32_t lane = vx_thread_id();
480	    uint32_t block_row = lane / cfg::tcN;
481	    uint32_t block_col = lane % cfg::tcN;
482	    uint32_t m_stride  = cfg::tcM;
483	    uint32_t n_stride  = cfg::tcN;
484	    if constexpr (dst_layout == col_major) {
485	      std::swap(block_row, block_col);
486	    }
