122	  void tick() {
123	    // 1) drain one response and route it to the source that issued it.
124	    auto& rsp = simobject_->lmem_rsp_in;
125	    if (!rsp.empty()) {
126	      auto& r = rsp.peek();
127	      uint32_t source = unpack_source(r.tag);
128	      uint32_t sub_tag = unpack_sub_tag(r.tag);
129	      if (source < kNumSources) {
130	        auto& buf = bufs_.at(source);
131	        auto it = buf.inflight_.find(sub_tag);
132	        if (it != buf.inflight_.end()) {
133	          if (r.data) buf.resident_[it->second] = r.data;
134	          buf.inflight_.erase(it);
135	        }
136	      }
137	      rsp.pop();
138	    }
139	
140	    // 2) round-robin pick one source with pending work and submit one req.
141	    auto& req = simobject_->lmem_req_out;
142	    if (req.full()) return;
143	    for (uint32_t i = 0; i < kNumSources; ++i) {
144	      uint32_t s = (rr_next_ + i) % kNumSources;
145	      auto& buf = bufs_.at(s);
146	      if (buf.pending_q_.empty()) continue;
147	      uint64_t addr = buf.pending_q_.front();
148	      uint32_t sub_tag = buf.next_tag_++;
149	      uint32_t tag = pack_tag(s, sub_tag);
150	      MemReq m(MemOp::LD, addr, /*data*/nullptr, /*byteen*/0, tag, /*hart_id*/0, /*uuid*/0);
151	      m.flags.local = 1;   // TCU TBUF reads from LMEM
152	      req.send(m, 1);
153	      buf.inflight_[sub_tag] = addr;
154	      buf.pending_q_.pop_front();
155	      ++buf.reads_;
156	      rr_next_ = (s + 1) % kNumSources;
157	      break;
158	    }
159	  }
