        break;
    #ifdef VX_CFG_TCU_WGMMA_ENABLE
      case TcuType::WGMMA:
      case TcuType::WGMMA_SP: {
        uint32_t a_desc = rs1_data.empty() ? 0 : rs1_data.at(0).u32;
