1358	  // Per-block guard: execute already happened for this trace; reset on pop().
1359	  std::array<bool, VX_CFG_NUM_TCU_BLOCKS> exec_done_;
1360	  // Per-block bitmask of warp IDs with planned WGMMA lines; cleared on fu_unlock.
